<?php require __DIR__.'/layouts/admin_start.php'; ?>
<section class="module-panel"><h2><?= $edit?'Modifier la pharmacie':'Nouvelle pharmacie' ?></h2><form method="POST"><?= csrfField() ?><input type="hidden" name="action" value="pharmacy"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="fields"><?php foreach(['name'=>'Nom','commune'=>'Commune','address'=>'Adresse','phone'=>'Téléphone'] as $key=>$label): ?><div><label for="<?= $key ?>"><?= $label ?></label><input id="<?= $key ?>" name="<?= $key ?>" required maxlength="<?= ['name'=>190,'address'=>255,'commune'=>100,'phone'=>25][$key] ?>" value="<?= htmlspecialchars($edit[$key]??'') ?>"></div><?php endforeach; ?></div><div class="form-actions"><button class="header-btn primary-btn">Enregistrer</button><?php if($edit): ?><a class="header-btn secondary-btn" href="/admin/pharmacies-de-garde">Annuler</a><?php endif; ?></div></form></section>
<section class="module-panel"><h2>Pharmacies enregistrées</h2><table><thead><tr><th>Nom</th><th>Commune</th><th>Adresse</th><th>Téléphone</th><th>Actions</th></tr></thead><tbody><?php foreach($pharmacies as $p): ?><tr><?php foreach(['name','commune','address','phone'] as $k): ?><td><?= htmlspecialchars($p[$k]) ?></td><?php endforeach; ?><td><a class="btn btn-warning" href="?modifier=<?= (int)$p['id'] ?>">Modifier</a> <a class="btn btn-primary" href="?pharmacie=<?= (int)$p['id'] ?>#garde">Programmer</a></td></tr><?php endforeach; ?><?php if(!$pharmacies): ?><tr><td colspan="5">Aucune pharmacie enregistrée.</td></tr><?php endif; ?></tbody></table></section>
<section class="module-panel" id="garde"><h2>Programmer une garde</h2><form method="POST"><?= csrfField() ?><input type="hidden" name="action" value="schedule"><div class="fields"><div><label for="pharmacy">Pharmacie</label><select id="pharmacy" name="id" required><option value="">Sélectionner</option><?php foreach($pharmacies as $p): ?><option value="<?= (int)$p['id'] ?>" <?= (int)($_GET['pharmacie']??0)===(int)$p['id']?'selected':'' ?>><?= htmlspecialchars($p['name'].' — '.$p['commune']) ?></option><?php endforeach; ?></select></div><div><label for="start_at">Début de garde</label><input type="datetime-local" id="start_at" name="start_at" required></div><div><label for="end_at">Fin de garde</label><input type="datetime-local" id="end_at" name="end_at" required></div></div><div class="form-actions"><button class="header-btn primary-btn" <?= !$pharmacies?'disabled':'' ?>>Enregistrer la garde</button></div></form></section>
<section class="module-panel"><h2>Historique des gardes</h2><table><thead><tr><th>Pharmacie</th><th>Début</th><th>Fin</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $g): ?><tr><td><?= htmlspecialchars($g['name'].' — '.$g['commune']) ?></td><td><?= GuardPharmacy::date((int)$g['start_at']) ?></td><td><?= GuardPharmacy::date((int)$g['end_at']) ?></td><td><?= $g['cancelled']?'Annulée':($g['start_at']>time()?'Programmée':($g['end_at']<=time()?'Terminée':'En cours')) ?></td><td><?php if(!$g['cancelled']&&$g['end_at']>time()): ?><form method="POST"><?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$g['id'] ?>"><button class="btn btn-danger" name="action" value="cancel">Annuler</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5">Aucune garde enregistrée.</td></tr><?php endif; ?></tbody></table><div class="module-pagination"><?php if($page>1): ?><a href="?page=<?= $page-1 ?>">Précédent</a><?php endif; ?><?php if($more): ?><a href="?page=<?= $page+1 ?>">Suivant</a><?php endif; ?></div></section><?php require __DIR__.'/layouts/admin_end.php'; ?>
